('efa42513-19e9-470e-b758-597f5314bf13','MA','a04040a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',8.5,90.6,362,5,'active'),
('3a1691fc-5eed-427d-9d30-43b4794daea3','MA','a04040a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Riad Al Hoceima Budget SARL','Riad Al Hoceima Budget','stay',1,'verified',ARRAY['en','fr'],'A clean, friendly guesthouse in the heart of the medina. Shared bathrooms, rooftop terrace, and free mint tea. Perfect for backpackers and solo travelers.',4.4,90,37,3.7,'active'),
('579f58dd-841e-4088-8cee-d7cff702a7c4','MA','a04040a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Al Hoceima Boutique SARL','Dar Al Hoceima Boutique','stay',3,'verified',ARRAY['en','fr','es'],'A beautifully restored 19th-century riad with 8 rooms, each uniquely decorated with antiques and local textiles. Plunge pool, hammam, and breakfast on the rooftop.',2,96.6,223,4.3,'active'),
('76bce527-fc7a-4fd1-b5ba-d0ce0cd652ad','MA','a04040a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Palais Al Hoceima Royal SARL','Palais Al Hoceima Royal','stay',4,'verified',ARRAY['en','fr','it','de'],'A former palace converted into an all-suite luxury hotel. Private butlers, Michelin-trained chef, spa, and curated excursions. The finest address in the city.',3.5,93.9,67,4.6,'active'),
('9b2fe0ab-ed3f-4372-afff-944b870b4fdc','MA','a04040a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Al Hoceima Tours SARL','Street Food Al Hoceima Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',9.9,93.9,44,4.5,'active'),
('f1e45c46-bad8-4a2a-a840-7847d9717149','MA','a04040a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Al Hoceima Family Kitchen SARL','Table Al Hoceima Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',10.9,90.9,400,4.4,'active'),
('ec04349e-0677-48d6-9c97-7744cb0acce3','MA','a04040a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Al Hoceima SARL','Le Salon Al Hoceima','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',11.3,96.3,167,5,'active'),
('c11738de-b150-4730-a4d5-9f7c8180f774','MA','a04040a0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Al Hoceima Adventure Club SARL','Al Hoceima Adventure Club','activity',2,'verified',ARRAY['en','fr','ar'],'A local outdoor club offering hiking, cycling, and climbing for all levels. Certified guides, quality equipment, and a passion for sharing Morocco''s natural beauty.',5,96.2,102,3.8,'active'),
